export interface LedgerBucket {
  count?: number;
  amount?: number;
  co2Emissions?: number;
}

export interface LedgerSubcategoryRow {
  key?: string;
  label?: string;
  co2Emissions?: number;
  count?: number;
}

export interface LedgerHistogramBucket {
  label: string;
  count: number;
}

export interface LedgerParameterMonth {
  bucket: string;
  electricityUse?: number;
  fuelUse?: number;
  transportation?: number;
  waterUse?: number;
  rawMaterials?: number;
  chemicalUse?: number;
}

export interface LedgerInventoryDisplay {
  subcategoryBreakdown?: LedgerSubcategoryRow[];
  co2Histogram?: LedgerHistogramBucket[];
  parameterMonthly?: LedgerParameterMonth[];
  topHotspots?: Array<{
    description?: string;
    category?: string;
    vendor?: string;
    emissions?: number;
    amount?: number;
  }>;
}

export interface LedgerAnalyticsPayload {
  totalCO2Emissions?: number;
  totalTransactions?: number;
  categoryBreakdown?: Record<string, LedgerBucket>;
  monthlyTrend?: Record<string, LedgerBucket>;
  inventoryDisplay?: LedgerInventoryDisplay;
}

const toNumber = (value: unknown): number => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

export function ledgerCategoryChartRows(
  breakdown: Record<string, LedgerBucket> | null | undefined
): Array<{ category: string; emissions: number; sharePercent: number }> {
  const rows = Object.entries(breakdown || {})
    .map(([category, bucket]) => ({
      category,
      emissions: toNumber(bucket?.co2Emissions),
    }))
    .filter((row) => row.emissions > 0)
    .sort((left, right) => right.emissions - left.emissions);
  const total = rows.reduce((sum, row) => sum + row.emissions, 0);
  return rows.map((row) => ({
    ...row,
    sharePercent: total > 0 ? Math.round((row.emissions / total) * 1000) / 10 : 0,
  }));
}

export function ledgerSubcategoryChartRows(
  rows: LedgerSubcategoryRow[] | null | undefined
): Array<{ key: string; label: string; emissions: number; sharePercent: number }> {
  const kept = (rows || [])
    .map((row, index) => ({
      key: String(row.key || `sub-${index}`),
      label: String(row.label || row.key || 'Unspecified'),
      emissions: toNumber(row.co2Emissions),
    }))
    .filter((row) => row.emissions > 0);
  const total = kept.reduce((sum, row) => sum + row.emissions, 0);
  return kept.map((row) => ({
    ...row,
    sharePercent: total > 0 ? Math.round((row.emissions / total) * 1000) / 10 : 0,
  }));
}

export function ledgerPeriodRows(
  monthlyTrend: Record<string, LedgerBucket> | null | undefined
): Array<{ period: string; totalAmount: number; totalCO2Emissions: number; transactionCount: number }> {
  return Object.entries(monthlyTrend || {})
    .filter(([period]) => period.length > 0)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([period, bucket]) => ({
      period,
      totalAmount: toNumber(bucket?.amount),
      totalCO2Emissions: toNumber(bucket?.co2Emissions),
      transactionCount: toNumber(bucket?.count),
    }));
}
